#' Methane generated by one waste stream with the IPCC first order decay model
#'
#' Follows IPCC 2006 Vol. 5 Ch. 3 (Eq. 3.4 to 3.6). Waste deposited in year t
#' starts to decay in year t + 1, which matches the IPCC spreadsheet with the
#' default delay (M = 13).
#'
#' @param deposits tonnes of wet waste deposited per year
#' @param doc degradable organic carbon, fraction of wet weight
#' @param k decay rate (1/yr)
#' @param mcf methane correction factor of the site
#' @param docf fraction of DOC that decomposes
#' @param f fraction of methane in landfill gas
#' @return tonnes of CH4 generated per year, same length as `deposits`
#' @export
fod_ch4 <- function(deposits, doc, k, mcf, docf = 0.5, f = 0.5) {
  ddocm <- deposits * doc * docf * mcf
  e <- exp(-k)
  stock <- as.numeric(stats::filter(ddocm, e, method = "recursive"))  # stock at end of each year
  decomposed <- c(0, utils::head(stock, -1)) * (1 - e)
  decomposed * f * 16 / 12
}

ramp_value <- function(fun, years) {
  if (is.null(fun)) return(rep(0, length(years)))
  if (is.numeric(fun)) return(rep(fun, length.out = length(years)))
  fun(years)
}

#' Landfill methane for one region
#'
#' @param act activity list from [region_activity()]
#' @param params parameter list, see [default_params()]
#' @param policy named list of functions year -> applicability share
#' @return data frame by year and site type with generated, recovered,
#'   oxidised and emitted CH4 (t), plus the activity needed for costing
#' @export
landfill_emissions <- function(act, params, policy = list()) {
  years <- act$years
  div <- ramp_value(policy$organics_diversion, years)
  a_energy <- ramp_value(policy$lfg_energy, years)
  a_flare <- ramp_value(policy$lfg_flaring, years)
  a_bio <- ramp_value(policy$biocover, years)
  eff_lfg <- params$eff[["lfg_flaring"]]
  eff_lfg_e <- params$eff[["lfg_energy"]]
  ox_bio <- params$eff[["biocover"]]
  k <- params$k[act$climate, ]

  out <- vector("list", length(SITE_TYPES))
  for (s in SITE_TYPES) {
    managed <- grepl("^managed", s)
    gen <- 0
    for (w in WASTE_TYPES) {
      dep <- act$landfilled[, w] * act$site_share[[s]]
      if (w %in% c("food", "garden")) dep <- dep * (1 - div)
      gen <- gen + fod_ch4(dep, params$doc[[w]], k[[w]], params$mcf[[s]], params$docf, params$f)
    }
    if (managed) {
      rec_energy <- gen * a_energy * eff_lfg_e
      rec_flare <- gen * (1 - a_energy) * a_flare * eff_lfg
    } else {
      rec_energy <- rec_flare <- 0 * gen
    }
    surface <- gen - rec_energy - rec_flare
    ox_def <- if (managed) params$ox_managed else params$ox_unmanaged
    ox_cover <- max(ox_def, ox_bio)
    emitted <- surface * ((1 - a_bio) * (1 - ox_def) + a_bio * (1 - ox_cover))
    out[[s]] <- data.frame(
      year = years, site = s, generated = gen, recovered_energy = rec_energy,
      recovered_flared = rec_flare, emitted = emitted,
      oxidised = surface - emitted, to_biocover = surface * a_bio
    )
  }
  res <- do.call(rbind, out)
  rownames(res) <- NULL
  attr(res, "diverted_t") <- rowSums(act$landfilled[, c("food", "garden")]) *
    sum(unlist(act$site_share)) * div
  res
}
